function render({width,state,params}) {
  const w = Number.isFinite(width) ? Math.max(320, Math.min(760, width)) : 640;
  const h = 250;
  const p = params || {};
  const index = Number.isFinite(p.sample) ? Math.max(1, Math.min(4, Math.round(p.sample))) : 1;
  const key = typeof state === 'string' ? state : state && state.key;
  const mode = key === 'mean' ? 'mean' : 'sample';
  const ink = '#272b2e', blue = '#356f9f', orange = '#c87532', quiet = '#d6d2c9';
  const gradients = [[3,1],[-1,3],[2,-1],[0,1]];
  const sum = gradients.reduce((a,g) => [a[0]+g[0], a[1]+g[1]], [0,0]);
  const mean = sum.map(v => v / gradients.length);
  const domain = {x:[-1.8,4], y:[-1.6,3.9]};
  const spanX = domain.x[1]-domain.x[0], spanY = domain.y[1]-domain.y[0];
  const scale = Math.min((w-68)/spanX,154/spanY);
  const plotWidth = spanX*scale, plotHeight = spanY*scale;
  const plotLeft = (w-plotWidth)/2, plotTop = 34+(154-plotHeight)/2;
  function point(v) {
    return {x:plotLeft+(v[0]-domain.x[0])*scale, y:plotTop+(domain.y[1]-v[1])*scale};
  }
  function text(x,y,t,anchor,color,size) {
    return '<text x="'+x+'" y="'+y+'" text-anchor="'+(anchor||'start')+'" fill="'+(color||ink)+'" font-size="'+(size||14)+'">'+t+'</text>';
  }
  const origin = point([0,0]);
  const endpoints = gradients.map(point);
  const meanEnd = point(mean);
  const arrows = [];
  function arrow(end,color,stroke,opacity) {
    const dx=end.x-origin.x, dy=end.y-origin.y;
    const length=Math.hypot(dx,dy), ux=dx/length, uy=dy/length;
    const head=[{x:end.x,y:end.y},{x:end.x-8*ux+4*uy,y:end.y-8*uy-4*ux},{x:end.x-8*ux-4*uy,y:end.y-8*uy+4*ux}];
    arrows.push({start:origin,end:end,head:head,color:color,stroke:stroke,opacity:opacity});
    return '<g opacity="'+opacity+'"><line x1="'+origin.x+'" y1="'+origin.y+'" x2="'+end.x+'" y2="'+end.y+'" stroke="'+color+'" stroke-width="'+stroke+'"/><polygon points="'+head.map(q=>q.x+','+q.y).join(' ')+'" fill="'+color+'"/></g>';
  }
  let body='<rect width="'+w+'" height="'+h+'" fill="#fbf8f1"/>';
  body+='<line x1="16" y1="16" x2="34" y2="16" stroke="'+orange+'" stroke-width="3"/>'+text(40,21,'样本梯度');
  body+='<line x1="150" y1="16" x2="168" y2="16" stroke="'+blue+'" stroke-width="3"/>'+text(174,21,'同一数据均值');
  const xStart=point([domain.x[0],0]), xEnd=point([domain.x[1],0]);
  const yStart=point([0,domain.y[0]]), yEnd=point([0,domain.y[1]]);
  body+='<path d="M '+xStart.x+' '+xStart.y+' H '+xEnd.x+' M '+yStart.x+' '+yStart.y+' V '+yEnd.y+'" fill="none" stroke="'+quiet+'"/>';
  body+=text(xEnd.x+8,origin.y+5,'g₁')+text(origin.x+8,yEnd.y+8,'g₂')+text(origin.x-8,origin.y+18,'0','end');
  gradients.forEach((g,i)=>{
    body+=arrow(endpoints[i],orange,mode==='sample' && i===index-1 ? 3.5 : 2,mode==='sample' && i!==index-1 ? 0.55 : 1);
  });
  body+=arrow(meanEnd,blue,3.5,1);
  body+=text(endpoints[0].x,endpoints[0].y-10,'(3,1)','end');
  body+=text(endpoints[1].x,endpoints[1].y-10,'(−1,3)');
  body+=text(endpoints[2].x+6,endpoints[2].y+6,'(2,−1)');
  body+=text(endpoints[3].x-8,endpoints[3].y-8,'(0,1)','end');
  body+=text(meanEnd.x+8,meanEnd.y+20,'(1,1)','start',blue);
  const chosen=gradients[index-1];
  body+=text(w/2,211,mode==='mean' ? '¼Σgᵢ = E[gᵢ] = (1,1)' : 'i = '+index+'    gᵢ = ('+chosen.join(',')+')','middle',mode==='mean' ? blue : ink,16);
  body+=text(w/2,237,'手选例：同一点 x = (0,0)。','middle');
  return {svg:'<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'" role="img" font-family="sans-serif"><title>单样本与平均梯度</title><desc>横纵轴是梯度分量 g₁、g₂，单位像素尺度相同。四个样本等概率，各梯度为所标坐标；蓝色箭头始终是这四个梯度的精确平均值。当前样本编号为'+index+'。箭头不表示参数更新轨迹。</desc>'+body+'</svg>',facts:{width:w,height:h,state:mode,parameterPoint:[0,0],sampleGradients:gradients,sampleProbabilities:[0.25,0.25,0.25,0.25],gradientSum:sum,expectedGradient:mean,selectedIndex:index,selectedGradient:chosen,compatibleLosses:gradients.map(g=>({form:'0.5*((x1+b1)^2+(x2+b2)^2)',b:g})),domain:domain,coordinateMeaning:'梯度分量',layout:{pixelsPerUnitX:scale,pixelsPerUnitY:scale,plotLeft:plotLeft,plotTop:plotTop,plotWidth:plotWidth,plotHeight:plotHeight,plotCenterX:plotLeft+plotWidth/2},origin:origin,sampleEndpoints:endpoints,meanEndpoint:meanEnd,arrows:arrows,parameterUpdates:[],steps:[{operation:'选择样本',index:index},{operation:'同一组四个梯度均匀加权求和',weights:[0.25,0.25,0.25,0.25],result:mean}]}};
}

function render({width,state,params}) {
  const w=Number.isFinite(width) ? Math.max(320,Math.min(760,width)) : 640;
  const p=params||{};
  const n=Number.isFinite(p.n) ? Math.max(2,Math.min(24,Math.round(p.n))) : 12;
  const key=typeof state==='string' ? state : state && state.key;
  const mode=key==='once'||key==='shuffle' ? key : 'coverage';
  const cols=Math.min(n,w>=560 ? 12 : 8), rows=Math.ceil(n/cols);
  const h=152+52*rows;
  const ink='#272b2e', blue='#356f9f', orange='#c87532', quiet='#ded9cf';
  function generator(seed) {
    let s=seed>>>0;
    return function() {s=(Math.imul(1664525,s)+1013904223)>>>0;return s/4294967296;};
  }
  const replacementSeed=20261010, shuffleSeed=20261011;
  const random=generator(replacementSeed), shuffleRandom=generator(shuffleSeed);
  const draws=[], counts=Array(n).fill(0);
  for(let t=0;t<n;t++){const i=Math.floor(random()*n);draws.push(i+1);counts[i]++;}
  const permutation=Array.from({length:n},(_,i)=>i+1), swaps=[];
  for(let i=n-1;i>0;i--){const j=Math.floor(shuffleRandom()*(i+1));const a=permutation[i];permutation[i]=permutation[j];permutation[j]=a;swaps.push({i:i,j:j});}
  const p0=Math.pow(1-1/n,n), p1=Math.pow(1-1/n,n-1), p2=1-p0-p1;
  const probabilities=[p0,p1,p2];
  const covered=counts.filter(c=>c>0).length;
  const empiricalCategories=[counts.filter(c=>c===0).length,counts.filter(c=>c===1).length,counts.filter(c=>c>=2).length];
  const colors=[quiet,blue,orange];
  const segments=[], cells=[];
  function text(x,y,t,anchor,color,weight){return '<text x="'+x+'" y="'+y+'" text-anchor="'+(anchor||'start')+'" fill="'+(color||ink)+'" font-size="14" font-weight="'+(weight||400)+'">'+t+'</text>';}
  let body='<rect width="'+w+'" height="'+h+'" fill="#fbf8f1"/>';
  body+=text(16,18,'有放回概率')+text(w-16,18,'n = '+n,'end');
  let start=16;
  probabilities.forEach((prob,i)=>{
    const span=(w-32)*prob;
    const active=(mode==='coverage'&&i===0)||(mode==='once'&&i===1);
    segments.push({category:i===2 ? '至少两次' : i+'次',probability:prob,x:start,y:30,width:span,height:24,highlighted:active});
    body+='<rect x="'+start+'" y="30" width="'+span+'" height="24" fill="'+colors[i]+'"'+(active ? ' stroke="'+ink+'" stroke-width="2"' : '')+'/>';
    body+=text(start+span/2,47,(prob*100).toFixed(1)+'%','middle',i===0 ? ink : '#ffffff');
    start+=span;
  });
  ['0次','1次','≥2次'].forEach((label,i)=>{
    const x=16+(w-32)*(i+0.5)/3;
    body+='<circle cx="'+(x-25)+'" cy="70" r="4" fill="'+colors[i]+'"/>'+text(x-15,75,label);
  });
  const panelStarts=[92,92+22+26*rows];
  const series=[counts,Array(n).fill(1)];
  body+=text(16,panelStarts[0],'有放回：覆盖 '+covered+'/'+n);
  body+=text(16,panelStarts[1],'打乱遍历：覆盖 '+n+'/'+n,'start',ink,mode==='shuffle' ? 700 : 400);
  series.forEach((values,panel)=>{
    values.forEach((count,i)=>{
      const x=16+(w-32)/cols*(i%cols+0.5);
      const y=panelStarts[panel]+20+26*Math.floor(i/cols);
      const fill=count===0 ? quiet : count===1 ? blue : orange;
      cells.push({method:panel===0 ? '有放回' : '打乱遍历',sampleIndex:i+1,count:count,cx:x,cy:y,radius:10,fill:fill});
      body+='<circle cx="'+x+'" cy="'+y+'" r="10" fill="'+fill+'"/>'+text(x,y+5,String(count),'middle',count===0 ? ink : '#ffffff');
    });
  });
  body+=text(w/2,h-10,'固定种子例；格内为抽中次数。','middle');
  return {svg:'<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'" role="img" font-family="sans-serif"><title>一轮抽样的覆盖</title><desc>理论概率针对有放回抽样。下方每组格子按样本编号顺序排列，对应位置是同一个样本。蓝色为一次，橙色为至少两次，灰色为零次。固定示例覆盖'+covered+'个样本；打乱遍历覆盖全部'+n+'个样本。</desc>'+body+'</svg>',facts:{width:w,height:h,state:mode,n:n,drawCount:n,probabilities:{omitted:p0,exactlyOnce:p1,atLeastTwice:p2,covered:1-p0},expectedCategoryCounts:probabilities.map(v=>n*v),generator:{name:'LCG32',multiplier:1664525,increment:1013904223,modulus:4294967296,replacementSeed:replacementSeed,shuffleSeed:shuffleSeed},replacement:{draws:draws,countsBySample:counts,covered:covered,categoryCounts:empiricalCategories},shuffle:{permutation:permutation,swaps:swaps,countsBySample:series[1],covered:n},layout:{columns:cols,rows:rows,probabilitySegments:segments,sampleCells:cells},steps:{replacement:'每步更新种子，取 floor(u*n)+1，累计 n 次',shuffle:'Fisher–Yates：i 从 n−1 到 1，交换 i 与 floor(u*(i+1))'}}};
}
